import { GoogleGenAI, Type } from "@google/genai";
import { UserData, BusinessPlan } from "../types";

const SYSTEM_INSTRUCTION = `أنت مستشار أعمال خبير في السوق المصري. هدفك هو إنشاء خطط عمل واقعية وقابلة للتنفيذ. 
يجب عليك تحليل ميزانية المستخدم بدقة شديدة. إذا كانت الميزانية منخفضة، اقترح مشاريع قائمة على الخدمات أو العمل الحر. 
ضع في اعتبارك الثقافة المحلية في المدن المصرية (مثل القاهرة، المنيا، ملوى، إلخ). 
يجب أن يكون الإخراج باللغة العربية وفي شكل JSON صالح فقط.`;

const BUSINESS_PLAN_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    projectName: { type: Type.STRING },
    identity: {
      type: Type.OBJECT,
      properties: {
        logoConcept: { type: Type.STRING },
        brandColors: { type: Type.ARRAY, items: { type: Type.STRING } },
      },
      required: ["logoConcept", "brandColors"],
    },
    concept: { type: Type.STRING },
    type: { type: Type.STRING },
    feasibility: {
      type: Type.OBJECT,
      properties: {
        estimatedCost: { type: Type.STRING },
        launchTimeline: { type: Type.STRING },
        timeToProfit: { type: Type.STRING },
      },
      required: ["estimatedCost", "launchTimeline", "timeToProfit"],
    },
    learningPath: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          skill: { type: Type.STRING },
          resource: { type: Type.STRING },
        },
        required: ["skill", "resource"],
      }
    },
    marketingStrategy: { type: Type.ARRAY, items: { type: Type.STRING } },
    swot: {
      type: Type.OBJECT,
      properties: {
        strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
        weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
        opportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
        threats: { type: Type.ARRAY, items: { type: Type.STRING } },
      },
      required: ["strengths", "weaknesses", "opportunities", "threats"],
    },
  },
  required: ["projectName", "identity", "concept", "type", "feasibility", "learningPath", "marketingStrategy", "swot"],
};

export class AiBusinessService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  }

  async generateBusinessPlan(userData: UserData): Promise<BusinessPlan> {
    const model = "gemini-3-pro-preview";

    // 1. Brainstorm Phase
    const brainstormPrompt = `بناءً على البيانات التالية لمستخدم مصري، اقترح 3 أفكار مشاريع مبتكرة ومناسبة لموقعه وميزانيته ومهاراته:
    ${JSON.stringify(userData)}
    الإخراج يجب أن يكون قائمة قصيرة من 3 أفكار مع وصف موجز لكل منها.`;

    const brainstormResponse = await this.ai.models.generateContent({
      model,
      contents: brainstormPrompt,
      config: { systemInstruction: SYSTEM_INSTRUCTION }
    });

    const draftIdeas = brainstormResponse.text;

    // 2. Critique Phase (Self-Correction)
    const critiquePrompt = `بصفتك محلل أعمال أول، قم بنقد هذه الأفكار الثلاثة:
    ${draftIdeas}
    حلل مدى واقعية كل فكرة لميزانية ${userData.budget} في مصر، ومدى المنافسة، والعوائد المتوقعة. اختر الفكرة الأفضل بينهم ووضح سبب اختيارها.`;

    const critiqueResponse = await this.ai.models.generateContent({
      model,
      contents: critiquePrompt,
      config: { systemInstruction: SYSTEM_INSTRUCTION }
    });

    const critiqueResult = critiqueResponse.text;

    // 3. Final Refinement and Plan Generation
    const finalPrompt = `بناءً على الأفكار الأولية:
    ${draftIdeas}
    وبناءً على التحليل والنقد التالي:
    ${critiqueResult}
    قم بإنشاء خطة عمل كاملة ومفصلة للفكرة المختارة. يجب أن تلتزم تماماً بهيكل الـ JSON المحدد.`;

    const finalResponse = await this.ai.models.generateContent({
      model,
      contents: finalPrompt,
      config: { 
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: BUSINESS_PLAN_SCHEMA as any
      }
    });

    try {
      const plan = JSON.parse(finalResponse.text || "{}") as BusinessPlan;
      return plan;
    } catch (error) {
      console.error("Failed to parse AI response:", error);
      throw new Error("حدث خطأ أثناء معالجة خطة العمل. يرجى المحاولة مرة أخرى.");
    }
  }
}

