import React, { useState } from 'react';
import { UserData, Step } from '../types';
import { GOVERNORATES, BUDGET_RANGES, INTERESTS } from '../constants';
import { ChevronLeft, ChevronRight, Check } from 'lucide-react';

interface WizardFormProps {
  onComplete: (data: UserData) => void;
}

const WizardForm: React.FC<WizardFormProps> = ({ onComplete }) => {
  const [step, setStep] = useState<Step>(1);
  const [formData, setFormData] = useState<UserData>({
    name: '',
    age: '',
    location: GOVERNORATES[0],
    education: '',
    phone: '',
    budget: BUDGET_RANGES[0].value,
    fundingSource: '',
    hobbies: '',
    interests: [],
    riskTolerance: 'medium',
    goals: '',
    skills: '',
    willingnessToLearn: true,
    preference: 'both',
    businessType: 'service'
  });

  const updateField = (field: keyof UserData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleInterestToggle = (interest: string) => {
    const current = formData.interests;
    if (current.includes(interest)) {
      updateField('interests', current.filter(i => i !== interest));
    } else {
      updateField('interests', [...current, interest]);
    }
  };

