            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-3">مدى تقبلك للمخاطرة</label>
              <div className="flex gap-4">
                {['low', 'medium', 'high'].map(r => (
                  <button
                    key={r}
