              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">طبيعة المشروع</label>
                <div className="grid grid-cols-3 gap-3">
                  {['product', 'service', 'both'].map(b => (
                    <button
                      key={b}
                      onClick={() => updateField('businessType', b)}
                      className={`py-2 rounded-lg border text-sm transition-all ${
                        formData.businessType === b ? 'bg-blue-600 text-white border-blue-600' : 'bg-white border-gray-200'
                      }`}
                    >
                      {b === 'product' ? 'بيع منتجات' : b === 'service' ? 'تقديم خدمات' : 'مزيج'}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">أحلامك وأهدافك</label>
                <textarea 
