import { AiBusinessService } from './services/geminiService';
import { Sparkles, LayoutDashboard, History } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<'form' | 'loading' | 'dashboard'>('form');
  const [loadingStage, setLoadingStage] = useState(0);
  const [plan, setPlan] = useState<BusinessPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleFormComplete = async (userData: UserData) => {
    setView('loading');
    setLoadingStage(0);
    setError(null);

    const service = new AiBusinessService();

    // Simulated progress updates for better UX
    const interval = setInterval(() => {
      setLoadingStage(prev => (prev < 3 ? prev + 1 : prev));
    }, 4000);

    try {
      const generatedPlan = await service.generateBusinessPlan(userData);
      setPlan(generatedPlan);
      setView('dashboard');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "حدث خطأ غير متوقع.");
      setView('form');
    } finally {
      clearInterval(interval);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Navigation */}
      <nav className="bg-white border-b border-gray-100 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
              <Sparkles size={24} />
            </div>
            <h1 className="text-2xl font-black text-gray-900 tracking-tight">صانع <span className="text-blue-600">المشاريع</span></h1>
          </div>

          <div className="hidden md:flex items-center gap-8 text-sm font-medium text-gray-600">
            <a href="#" className="hover:text-blue-600 transition-colors">الرئيسية</a>
            <a href="#" className="hover:text-blue-600 transition-colors">الخطط المحفوظة</a>
            <a href="#" className="hover:text-blue-600 transition-colors">عن المنصة</a>
            <button className="bg-gray-100 text-gray-800 px-5 py-2 rounded-xl hover:bg-gray-200 transition-all font-bold">دخول</button>
          </div>
        </div>
      </nav>

      <main className="flex-1 container mx-auto px-4 py-12">
        {error && (
          <div className="max-w-xl mx-auto mb-8 bg-red-50 border-r-4 border-red-600 p-4 text-red-800 font-bold rounded-lg shadow-sm flex items-center gap-3">
             <span>⚠️ {error}</span>
             <button onClick={() => setError(null)} className="mr-auto text-xs underline">إغلاق</button>
          </div>
        )}

        {view === 'form' && (
          <div className="space-y-12">
            <div className="text-center space-y-4 max-w-2xl mx-auto">
              <h2 className="text-4xl md:text-5xl font-black text-gray-900 leading-tight">
                حول أحلامك إلى <span className="text-blue-600">واقع استثماري</span> مدروس
              </h2>
              <p className="text-lg text-gray-500">
                أجب عن بضع أسئلة وسيقوم وكيلنا الذكي بتحليل السوق المصري وبناء مشروع مخصص لك بالكامل، من الاسم وحتى استراتيجية التسويق.
              </p>
            </div>
            <WizardForm onComplete={handleFormComplete} />
          </div>
        )}

        {view === 'loading' && <Loader stage={loadingStage} />}

        {view === 'dashboard' && plan && (
          <div className="space-y-8">
            <div className="flex justify-between items-center mb-4">
               <button 
                onClick={() => setView('form')}
                className="text-blue-600 flex items-center gap-2 hover:bg-blue-50 px-4 py-2 rounded-lg transition-all"
               >
                 إنشاء مشروع جديد
               </button>
            </div>
            <BusinessDashboard plan={plan} />
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-gray-100 py-12">
        <div className="container mx-auto px-4 grid grid-cols-1 md:grid-cols-3 gap-8 text-center md:text-right">
          <div className="space-y-4">
            <h3 className="text-xl font-bold text-gray-900">صانع المشاريع AI</h3>
            <p className="text-sm text-gray-500 leading-relaxed">
              منصة مصرية رائدة تستخدم الذكاء الاصطناعي لتمكين رواد الأعمال وبناء اقتصاد وطني قوي عبر تحويل الأفكار لخطط حقيقية.
            </p>
          </div>
          <div className="space-y-4">
             <h4 className="font-bold text-gray-800">روابط سريعة</h4>
             <ul className="text-sm text-gray-500 space-y-2">
                <li><a href="#" className="hover:text-blue-600">دراسات جدوى جاهزة</a></li>
                <li><a href="#" className="hover:text-blue-600">شركاء النجاح</a></li>
                <li><a href="#" className="hover:text-blue-600">سياسة الخصوصية</a></li>
             </ul>
          </div>
          <div className="space-y-4">
             <h4 className="font-bold text-gray-800">تواصل معنا</h4>
             <p className="text-sm text-gray-500">القاهرة، جمهورية مصر العربية</p>
             <div className="flex justify-center md:justify-start gap-4 text-gray-400">
               {/* Icons placeholder */}
               <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center hover:bg-blue-500 hover:text-white transition-all cursor-pointer">F</div>
               <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center hover:bg-blue-400 hover:text-white transition-all cursor-pointer">T</div>
               <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center hover:bg-pink-500 hover:text-white transition-all cursor-pointer">I</div>
             </div>
          </div>
        </div>
        <div className="mt-12 text-center text-xs text-gray-400 border-t border-gray-50 pt-8">
           &copy; {new Date().getFullYear()} صانع المشاريع. جميع الحقوق محفوظة.
        </div>
      </footer>
    </div>
  );
};

export default App;
